mapper.update:
UPDATE vacation
SET del_yn        = 'Y',
    modified_date = NOW(),
    modified_nm   = #{modifiedNm}
WHERE vacation_id = #{vacationId}
  AND del_yn = 'N'

UPDATE vacation_history
SET del_yn        = 'Y',
    modified_date = NOW(),
    modified_nm   = #{modifiedNm}
WHERE history_id = #{historyId}
  AND del_yn = 'N'
